import {defineLesson as lesson} from './lesson-schema.js';

export const courseExpansion=[
lesson({id:'shell-lab',chapter:'linux',title:'Build a checked diagnostic script',description:'Turn shell commands into a repeatable report with quoting, explicit failures and useful exit status.',scene:'pipeline',sourceChapter:'Learning About Processes and Threads',goals:['Quote arguments correctly','Separate report data from errors','Test success and failure paths'],steps:[
 ['Contract','Define what success means','A diagnostic script is an interface. Decide which observations are mandatory and which are optional before choosing commands. A report that silently omits a failed check can look healthy. This exercise accepts an output directory, records the running kernel and memory information, and stops when the destination cannot be created. It runs as an ordinary user; it does not change system settings.','A report must distinguish missing evidence from a successful check.','report.sh OUTPUT_DIRECTORY','Contract: exit 0 only when the mandatory report has been written.' ],
 ['Arguments','Treat arguments as data','The shell performs word splitting and pathname expansion on unquoted parameter expansions. A path containing spaces must remain one argument. Validate the argument count, quote directory names, and use a predictable interpreter. Do not add sudo to make every failing path writable: an inaccessible destination is a legitimate failure the caller needs to see.','Quoting protects argument boundaries, not just spaces in filenames.',`#!/bin/sh\n[ "$#" -eq 1 ] || { printf 'usage: %s OUTPUT_DIRECTORY\n' "$0" >&2; exit 2; }\nout=$1\nmkdir -p -- "$out" || exit 1`,'A directory such as "report with spaces" is handled as one path.' ],
 ['Evidence','Write a deterministic report','Group the mandatory commands so their output goes to one file, but check each command rather than relying on the last command in the group. A POSIX pipeline normally reports the final command status, which can hide an earlier failure. Avoid assuming Bash-only pipefail exists in /bin/sh. Keep error messages on stderr, separate from the report file.','Choose the shell deliberately; do not mix incompatible shell features.',`{\n  uname -sr || exit 1\n  cat /proc/meminfo || exit 1\n} > "$out/system.txt" || exit 1`,'system.txt contains kernel identity followed by memory observations.' ],
 ['Failure','Test the unhappy paths','A script is not tested by one successful run. Invoke it without arguments, with a directory containing spaces, and with a destination underneath /proc that cannot be created. Inspect exit status immediately after each call. Do not use a privileged shell for these tests: doing so changes the permission behavior being tested. Preserve the error output as evidence.','The caller should be able to automate decisions from exit status.',`sh report.sh; printf 'status=%s\n' "$?"\nsh report.sh 'report with spaces'\nsh report.sh /proc/training-report; printf 'status=%s\n' "$?"`,'Usage error returns 2; an unwritable destination returns nonzero.' ],
 ['Integrate','Keep automation maintainable','Store the script beside a short description of its inputs, output format and tested shell. Check syntax with sh -n before executing it. Add ShellCheck in development if available, but understand its findings rather than suppressing them wholesale. An embedded image may only contain BusyBox applets, so validate against the actual target tools instead of assuming the workstation command set.','Portability is a tested property of the selected runtime.',`sh -n report.sh\ncommand -v shellcheck >/dev/null && shellcheck report.sh\nsh report.sh ./evidence`,'Retain script version, report and failure-test results together.' ]],lab:{objective:'Create an unprivileged system report script with explicit success and failure behavior.',setup:'A Linux shell with /proc mounted. Create report.sh using the three code fragments from the lesson.',commands:'sh -n report.sh\nsh report.sh "report with spaces"\ncat "report with spaces/system.txt"\nsh report.sh /proc/training-report\nprintf "status=%s\\n" "$?"',expected:'A readable report in the successful case; nonzero status and stderr for an unwritable destination.',troubleshooting:'Check interpreter, executable mode, argument quoting and redirection permissions. A missing optional tool is not a reason to run the entire script as root.',deliverable:'Script, successful report, and a table of tested inputs and exit statuses.'},quiz:{question:'What does a POSIX shell pipeline normally report?',options:['Every command status combined','The final command status','Always zero'],answer:1,why:'An earlier failed producer can be masked by a successful final consumer; check failures deliberately.'}}),
lesson({id:'localconf-lab',chapter:'yocto',title:'Audit an effective build configuration',description:'Use BitBake queries to separate build-local conveniences from product policy.',scene:'metadata',source:'Yocto-Project-Scarthgap-Learning-Handbook.pdf',sourceChapter:'Configuration',goals:['Query effective values','Classify configuration ownership','Retain a reproducible configuration record'],steps:[
 ['Scope','Start inside the intended build','The same source checkout can support several build directories with different machines, distributions and cache locations. Source the environment for the intended directory, then record its identity before editing configuration. A setting copied into an inactive build directory has no effect. Product choices belong in maintained metadata; workstation paths usually do not.','The active build directory is part of every command context.','pwd\nbitbake-layers show-layers','Record the build path and active layer paths.' ],
 ['Identity','Ask BitBake rather than reading one file','MACHINE and DISTRO may receive defaults and overrides from several configuration files. Query the resolved value and its history. A line in local.conf is only one input, not proof of the final value. Keep the output with the experiment so someone else can distinguish a configuration mistake from a source or hardware problem.','Effective metadata is the value actually used by the build.','bitbake-getvar MACHINE\nbitbake-getvar DISTRO','Each query prints the resolved value and available assignment history.' ],
 ['Caches','Separate reusable inputs from work output','DL_DIR stores fetched inputs while SSTATE_DIR stores reusable task outputs. TMPDIR contains build work and generated artifacts, including evidence needed for diagnosis. Use absolute paths with controlled access if sharing caches. Avoid world-writable directories as a convenience, and do not assume moving a cache changes the target product.','Cache sharing requires a trust and permissions policy.','bitbake-getvar DL_DIR\nbitbake-getvar SSTATE_DIR\nbitbake-getvar TMPDIR','Three paths with different lifetime and sharing requirements.' ],
 ['Policy','Move stable decisions to the right owner','A local image-package experiment can begin in local.conf, but the product image should ultimately own its package selection. A distro owns distribution-wide policy; a machine describes board-specific choices. Moving settings is not complete until the old local override is removed and the effective result is checked again. Make one change at a time.','Reproducibility means not depending on an undocumented developer override.','bitbake-getvar -r core-image-minimal IMAGE_INSTALL','Compare before and after moving an image choice into your layer.' ],
 ['Evidence','Capture a minimal build record','Retain layer commit IDs, selected configuration files, resolved machine and distro, image identity and the final manifest. Avoid publishing credentials or private mirror tokens in a raw environment dump. A record should explain how to recreate the build, not simply preserve a large amount of unrelated terminal output.','Review build records for secrets before sharing.','bitbake-layers show-layers\nbitbake-getvar -r core-image-minimal IMAGE_FSTYPES','A compact evidence bundle identifies configuration and expected artifacts.' ]],lab:{objective:'Audit one build and move one image choice from local experimentation to maintained metadata.',setup:'A sourced Scarthgap build. Use a training image rather than changing a production configuration.',commands:'bitbake-getvar MACHINE\nbitbake-getvar DISTRO\nbitbake-getvar DL_DIR\nbitbake-getvar SSTATE_DIR\nbitbake-getvar -r core-image-minimal IMAGE_INSTALL',expected:'You can name the active target and explain who owns each recorded setting.',troubleshooting:'If a change appears ignored, verify the sourced build directory, assignment history and overrides before cleaning anything.',deliverable:'Configuration ownership table and before/after effective-value evidence.'},quiz:{question:'Where should stable product image package selection normally live?',options:['Only in one developer local.conf','In the maintained product image metadata','In DL_DIR'],answer:1,why:'The product definition must travel with its maintained layer, not a private workstation setting.'}}),
lesson({id:'assignment-lab',chapter:'bitbake',title:'Predict and prove BitBake assignments',description:'Run a controlled expansion experiment before changing product metadata.',scene:'metadata',source:'Yocto-Project-Scarthgap-Learning-Handbook.pdf',sourceChapter:'Variables',goals:['Compare lazy and immediate expansion','Handle list spaces explicitly','Inspect assignment history'],steps:[
 ['Fixture','Use a controlled recipe context','Assignment behavior is easiest to understand when unrelated layers are removed from the question. Put the following variables in your own training recipe, not a vendor recipe. Prefix them with TRAIN so they cannot accidentally alter compilation or image policy. Predict the result on paper before querying BitBake.','Experiments should isolate semantics from product behavior.','TRAIN_BASE = "first"\nTRAIN_LAZY = "${TRAIN_BASE}"\nTRAIN_NOW := "${TRAIN_BASE}"\nTRAIN_BASE = "second"','Predict TRAIN_LAZY and TRAIN_NOW before running a query.' ],
 ['Expansion','Separate storage from expansion time','A normal assignment retains references for later expansion. Immediate assignment expands the right side when parsed. Changing TRAIN_BASE afterward therefore affects TRAIN_LAZY but not the earlier immediate snapshot. This distinction matters for paths and metadata derived from variables that are modified later by includes or overrides.','The same text can produce different results depending on expansion time.','bitbake-getvar -r training-hello TRAIN_LAZY\nbitbake-getvar -r training-hello TRAIN_NOW','TRAIN_LAZY="second"; TRAIN_NOW="first" for this fixture.' ],
 ['Defaults','Understand defaults before overriding','A question-mark assignment supplies a value only if the variable is not already set when the statement is parsed. A weak default uses different substitution semantics. Do not treat all default operators as interchangeable. Start with one question-mark example, inspect its history, and then consult the BitBake manual before introducing weak defaults into shared configuration.','Parse order can matter for default assignments.','TRAIN_MODE ?= "development"\nTRAIN_MODE = "release"\nbitbake-getvar -r training-hello TRAIN_MODE','The explicit assignment supplies release.' ],
 ['Lists','Keep list boundaries visible','The plus-equals operator inserts a space. Override-style append does not add one for you. An appended package name without a leading space can join the preceding name into a nonexistent package. Prepend places its text before the base value; it is not another spelling of append. Test strings that make missing boundaries obvious.','Many metadata list bugs are really whitespace bugs.','TRAIN_LIST = "alpha"\nTRAIN_LIST += "beta"\nTRAIN_LIST:append = " gamma"\nTRAIN_LIST:prepend = "start "','Resolved list: start alpha beta gamma.' ],
 ['Review','Explain provenance, not just the result','Retain the query output with assignment history and your prediction. When an actual product variable behaves unexpectedly, use the same approach to identify the file and operation responsible. Do not fix a misunderstood assignment by adding progressively stronger overrides. Remove the temporary TRAIN variables after recording the exercise.','A useful explanation identifies both the final value and its origin.','bitbake-getvar -r training-hello TRAIN_LIST','Match every word and space to an assignment in the fixture.' ]],lab:{objective:'Create an assignment fixture and explain every effective result.',setup:'Your own discovered training-hello recipe in a Scarthgap build. Add the TRAIN-prefixed snippets only.',commands:'bitbake-getvar -r training-hello TRAIN_LAZY\nbitbake-getvar -r training-hello TRAIN_NOW\nbitbake-getvar -r training-hello TRAIN_LIST',expected:'second, first, and start alpha beta gamma respectively.',troubleshooting:'Check that you queried the intended recipe. Inspect history for duplicate assignments and ensure literal ${TRAIN_BASE} was not expanded by a host shell while editing.',deliverable:'Prediction/result table and the temporary fixture diff.'},quiz:{question:'Does :append automatically insert a separating space?',options:['Yes','No','Only for IMAGE_INSTALL'],answer:1,why:'Include the required space in the appended string when extending a whitespace-separated list.'}}),
lesson({id:'hello-recipe-lab',chapter:'bitbake',title:'Ship your first C application',description:'Follow a local C source file through target compilation, packaging and image execution.',scene:'recipe',source:'Embedded-Linux-Development-Using-Yocto-Project-4th-Edition.pdf',sourceChapter:'Writing Recipes',goals:['Declare real source and license evidence','Compile with the target environment','Verify a packaged application'],steps:[
 ['Source','Begin with a small observable program','A tiny program keeps the integration exercise focused on the build system. Use puts to print one stable line and return success. Keep the source and its actual license file under your training layer. The example is intentionally not an application framework: its purpose is to make every step from source to delivered file visible.','Small fixtures make packaging failures easier to isolate.','#include <stdio.h>\nint main(void) { puts("training hello"); return 0; }','Runtime output: training hello' ],
 ['Recipe','Declare inputs and license evidence','Use training-hello_1.0.bb and local file entries for hello.c and LICENSE. Set LICENSE to the actual license and compute LIC_FILES_CHKSUM from that file. For the Scarthgap local-source fixture, S can point at WORKDIR. Later Yocto releases changed unpack staging conventions, so do not copy this directory assumption without checking release documentation.','License identity and the referenced checksum must describe the actual source.','SRC_URI = "file://hello.c file://LICENSE"\nS = "${WORKDIR}"\n# Compute LICENSE checksum with md5sum; do not invent it.','The layer owns source, license text and recipe metadata.' ],
 ['Compile','Use the supplied compiler and flags','The build supplies a compiler command that can include tuning and sysroot options. Use CC, CFLAGS and LDFLAGS instead of invoking the workstation gcc directly. A binary that compiles successfully for the host is not a successful target build. Keep compile output under the recipe work area rather than writing into the checkout or host installation paths.','Build success must include the intended architecture and ABI.','do_compile() {\n    ${CC} ${CFLAGS} ${S}/hello.c ${LDFLAGS} -o training-hello\n}','Inspect log.do_compile for the target compiler invocation.' ],
 ['Install','Stage the target path under D','The recipe installs into a staging root so package generation can inspect ownership and content. Use install with an explicit mode and prefix the destination with D. The ordinary bindir path is covered by standard runtime packaging defaults, but inspect the generated package instead of assuming a file was included merely because do_install completed.','Never install a recipe output directly into the workstation /usr/bin.','do_install() {\n    install -d ${D}${bindir}\n    install -m 0755 training-hello ${D}${bindir}/training-hello\n}','Staged target path: /usr/bin/training-hello.' ],
 ['Deliver','Verify package, image and behavior','Build the recipe, query package contents, then explicitly include its runtime package in a training image. Boot that image on the matching target and execute the program. The recipe build alone does not change an existing image. Retain the image manifest and terminal output so the evidence covers delivery rather than only compilation.','Compilation, image inclusion and runtime correctness are separate checks.','bitbake training-hello\noe-pkgdata-util list-pkg-files training-hello\n# On the rebuilt target:\ntraining-hello','Package contains the executable; matching target prints training hello.' ]],lab:{objective:'Deliver a locally authored C application through a Yocto image.',setup:'Create the recipe and local source/license in an owned layer. Use a real MIT license and its computed checksum. Scarthgap is the directory-layout baseline.',commands:'bitbake-layers show-recipes training-hello\nbitbake training-hello\noe-pkgdata-util list-pkg-files training-hello\nbitbake training-image',expected:'The recipe is discovered, the runtime package owns /usr/bin/training-hello and the rebuilt image runs it.',troubleshooting:'Check layer registration, file search paths, license checksum, target compiler and image selection. Exec format errors suggest an architecture mismatch.',deliverable:'Recipe, source, license, package listing, image manifest and target output.'},quiz:{question:'Why use ${CC} instead of gcc?',options:['To use the configured target compiler environment','To bypass licensing','To install directly on the host'],answer:0,why:'The build-provided compiler and flags carry the target architecture and sysroot configuration.'}}),
lesson({id:'patch-lab',chapter:'product',title:'Carry a reviewable application patch',description:'Turn a temporary change into a maintained layer patch and prove it survives a clean source preparation.',scene:'recipe',source:'Embedded-Linux-Development-Using-Yocto-Project-4th-Edition.pdf',sourceChapter:'Customizing Recipes',goals:['Create a focused patch','Resolve append file paths','Test maintained metadata rather than temporary edits'],steps:[
 ['Reproduce','Record the behavior being changed','Start from a known source revision and write the old and desired output. A patch without a reproduced issue is difficult to review later. For a training hello program, change one output string and explain that it is an exercise rather than a product fix. Keep the patch separate from unrelated formatting or compiler changes.','A patch should have a narrow, testable reason.','devtool modify training-hello','A managed workspace is prepared for source changes.' ],
 ['Commit','Make the source change attributable','Edit the workspace source, build it and commit a focused change. Include a useful subject and rationale; record upstream status appropriate to the real situation. Do not label a local training change as submitted upstream unless it actually was. Source history should make the patch understandable without requiring the original developer to explain it.','Patch metadata must be truthful.','git diff --check\ngit diff\ngit add hello.c\ngit commit -m "training: identify the layer-integrated build"','Review one intentional behavioral change.' ],
 ['Integrate','Bring the change back to your layer','Use devtool finish to integrate the managed source changes into the layer. Inspect the generated recipe or append and patch rather than treating the command as a black box. If creating an append manually, its filename must match the target recipe and its file search path must find the patch. Use an immediate expansion for the THISDIR-based path.','A patch on disk is not evidence that BitBake applies it.','devtool finish training-hello ../meta-training\nbitbake-layers show-appends','Inspect SRC_URI and the resolved patch path.' ],
 ['Rebuild','Test without the workspace override','Once the workspace override is removed, rebuild from maintained metadata. Inspect the patch task log and verify the changed runtime output. Do not rely on an edit left only in tmp/work: a later unpack can replace it. Use a disposable build for destructive clean-source experiments and preserve diagnostic evidence first.','The release must not depend on one developer workspace.','bitbake training-hello\nbitbake -c patch training-hello','The maintained patch is applied during source preparation.' ],
 ['Upgrade','Retest meaning after rebasing','A patch that applies without conflict can still be wrong against a newer upstream implementation. Reproduce the original behavior test after any source upgrade. Remove a patch when upstream provides the fix, rather than retaining unnecessary local divergence. The owner should know the upstream status and the condition under which the patch can disappear.','Textual applicability is weaker than semantic correctness.','git diff --check\n# Re-run the application behavior check on the target.','Retain old/new output and the layer commit containing the patch.' ]],lab:{objective:'Maintain one small source change through an owned layer.',setup:'A working training-hello recipe and devtool workspace support. Keep unrelated work committed before finishing the workspace.',commands:'devtool modify training-hello\n# Edit, test and commit source in the workspace.\ndevtool finish training-hello ../meta-training\nbitbake-layers show-appends\nbitbake training-hello',expected:'The layer contains the integration change, and the same changed behavior appears without a workspace override.',troubleshooting:'Check append matching, SRC_URI, FILESEXTRAPATHS and log.do_patch. A successful patch application does not replace a runtime regression test.',deliverable:'Focused patch, integration metadata, upstream-status explanation and target test evidence.'},quiz:{question:'Does a patch applying cleanly prove it is correct after an upgrade?',options:['Yes','No','Only when generated by Git'],answer:1,why:'The surrounding implementation may have changed semantically even when the textual context still matches.'}}),
lesson({id:'runtime-dependency-lab',chapter:'bitbake',title:'Prove a script runtime dependency',description:'Separate recipe build dependencies from packages needed by an installed script.',scene:'dependencies',source:'Yocto-Metadata-Dependencies-and-Recipe-Providers.pdf',sourceChapter:'Dependencies',goals:['Identify interpreter and command dependencies','Use package overrides','Inspect dependency closure'],steps:[
 ['Observe','Read the actual execution contract','A script may compile nothing but still need an interpreter and external commands on the target. A Bash shebang requires a suitable Bash runtime package. A POSIX sh script should not claim Bash-only features. List the commands it executes and identify their output packages using generated package data rather than guessing from recipe names.','A script has runtime dependencies even without a compile stage.','#!/bin/bash\nprintf "training dependency check\\n"','This fixture deliberately requires Bash.' ],
 ['Declare','Attach the dependency to the output package','For a script shipped by the main package, declare RDEPENDS:${PN} with the runtime package name. DEPENDS would populate a build-time recipe sysroot and does not express the same installation contract. The package override is essential because one recipe can emit several packages with different runtime needs.','Recipe names and output package names are distinct namespaces.','RDEPENDS:${PN} += "bash"','The main output package requires the bash runtime package.' ],
 ['Inspect','Use generated package data','Build the recipe so package metadata exists, then query the runtime dependency field. File dependency scanning may infer some requirements, but explicit requirements still need correct declarations where appropriate. Do not assume a large development image proves the dependency is declared: the interpreter may already be present for unrelated reasons.','A feature-rich development image can hide missing dependencies.','bitbake training-script\noe-pkgdata-util read-value RDEPENDS training-script','Inspect the recorded Bash dependency and any generated dependencies.' ],
 ['Compose','Check the minimal image closure','Include only the training package and the image baseline needed for boot. Build the image and inspect its manifest for the provider package. Execute the script on that image. If the interpreter is absent, the shell may report not found even though the script itself exists, so inspect the shebang and interpreter path before changing file permissions.','A file existing is not proof its execution environment exists.','head -n 1 /usr/bin/training-script\ncommand -v bash\n/usr/bin/training-script','The selected target contains Bash and the script executes.' ],
 ['Compare','Explain why build success was insufficient','Remove the dependency only in a disposable experiment and compare package metadata, manifests and behavior. Avoid broad clean commands: the question is dependency closure, not whether every component can rebuild from scratch. Record which observation would have caught the defect before shipping. Restore the correct declaration before retaining the layer.','Verify the dependency edge, not merely an accidentally successful image.','oe-pkgdata-util list-pkg-files bash','Evidence connects the declared package edge to the installed interpreter.' ]],lab:{objective:'Package a Bash fixture and prove its interpreter dependency reaches the image.',setup:'An owned training-script recipe installing the two-line fixture with mode 0755 and valid license metadata.',commands:'bitbake training-script\noe-pkgdata-util read-value RDEPENDS training-script\noe-pkgdata-util list-pkg-files bash\nbitbake training-image',expected:'The runtime dependency is recorded, Bash is in the image manifest, and the target script prints its message.',troubleshooting:'Check actual output package names and shebang paths. DEPENDS is not a replacement for a runtime package dependency.',deliverable:'Recipe diff, runtime metadata, image manifest and target execution evidence.'},quiz:{question:'Which variable expresses the installed script package requirement?',options:['DEPENDS only','RDEPENDS:${PN}','BBLAYERS'],answer:1,why:'RDEPENDS describes runtime package requirements; DEPENDS describes build-time recipe requirements.'}}),
lesson({id:'runtime-alias-lab',chapter:'bitbake',title:'Resolve a runtime package alias',description:'Follow an advertised package capability without confusing it with virtual build providers.',scene:'dependencies',source:'Yocto-Metadata-Dependencies-and-Recipe-Providers.pdf',sourceChapter:'Providers',goals:['Declare a runtime alias','Choose a deterministic provider','Inspect the installed implementation'],steps:[
 ['Contract','Name a runtime capability','Suppose two product implementations can supply a simple status command. A consumer can depend on an agreed runtime alias, but the implementations must actually honor the same interface. An alias does not rename files or enforce behavior. Define executable path, arguments, output and failure codes before allowing an implementation to advertise the capability.','A package alias is a metadata promise, not an interface validator.','Capability: training-status-api\nCommand: /usr/bin/training-status','Both implementations must satisfy the documented command contract.' ],
 ['Advertise','Add a package-level alias','The main output package of training-status-simple can advertise the alias with RPROVIDES. This is not recipe-level PROVIDES, which participates in build dependency resolution. Keep the concepts separate when inspecting logs: a missing build provider and an unresolved runtime dependency are different failures with different metadata owners.','Use the provider mechanism for the namespace being resolved.','RPROVIDES:${PN} += "training-status-api"','training-status-simple advertises the runtime alias.' ],
 ['Consume','Depend on the agreed capability','A consumer package can require training-status-api through RDEPENDS. That requirement is satisfied by an eligible output package advertising the name. Ensure the provider recipe is available in active metadata. Do not assume an alias is a mechanism for installing two conflicting implementations side by side; their file ownership and coexistence still need design.','Runtime aliases do not solve conflicting installed paths.','RDEPENDS:${PN} += "training-status-api"','The consumer records a capability requirement rather than one implementation name.' ],
 ['Select','Make multiple candidates deliberate','If several implementations advertise the alias, product metadata should make the preferred runtime provider explicit and test the result. Use PREFERRED_RPROVIDER for runtime selection, not PREFERRED_PROVIDER for a virtual build target. Prefer one initial provider in the exercise so the dependency graph is understandable before adding selection policy.','Provider selection belongs to maintained product policy.','PREFERRED_RPROVIDER_training-status-api = "training-status-simple"','The selected implementation is deterministic for this product configuration.' ],
 ['Validate','Test what the alias actually delivers','Build the image, inspect its manifest for the concrete package, then execute the interface tests. Package resolution only proves that metadata names can be satisfied. It does not establish response format, timing or error behavior. Run the same contract tests when switching providers, and retain the concrete implementation identity in release evidence.','Abstract dependencies still need concrete release inventory.','oe-pkgdata-util read-value RPROVIDES training-status-simple\n# On target:\ntraining-status','The manifest identifies the implementation and the interface test passes.' ]],lab:{objective:'Create one runtime alias, consume it and prove the installed implementation.',setup:'Two small owned packages: a status provider installing a command, and a consumer. Include actual source licenses.',commands:'bitbake training-status-simple\noe-pkgdata-util read-value RPROVIDES training-status-simple\nbitbake training-image',expected:'The consumer dependency resolves to the intended concrete package, whose command satisfies the documented contract.',troubleshooting:'Check whether the failure concerns a recipe provider or runtime package. Verify provider availability, output package name and selected runtime-provider policy.',deliverable:'Provider/consumer metadata, resolved manifest and command contract test.'},quiz:{question:'What does RPROVIDES automatically guarantee?',options:['Behavioral compatibility','A runtime package name can be advertised','Two packages can overwrite the same file safely'],answer:1,why:'Compatibility and file coexistence require separate design and tests.'}}),
lesson({id:'package-image-lab',chapter:'product',title:'Build and inspect an owned training image',description:'Make package selection reproducible and trace a requested feature to the final manifest.',scene:'image',source:'Yocto-Packaging-and-Image-Generation.pdf',sourceChapter:'Image Generation',goals:['Create an owned image recipe','Use real runtime package names','Compare image manifests'],steps:[
 ['Own','Create an image you can reproduce','A named image recipe is a better home for a maintained package set than an accumulation of developer-local edits. Start with core-image and add only the packages needed for the exercise. Do not copy a full vendor demo image without understanding its features and security defaults. The machine and distro remain separately selected configuration.','An image recipe defines composition, not every aspect of the board.','SUMMARY = "Training image"\nLICENSE = "MIT"\ninherit core-image\nIMAGE_INSTALL:append = " training-hello"','Save as recipes-core/images/training-image.bb in the owned layer.' ],
 ['Names','Resolve output packages deliberately','The recipe name is not necessarily the name of every package it produces. Use generated package data to find the executable owner. Package groups can express reusable feature sets, while image recipes choose which sets belong in a product. Do not add development headers or debug tools to production simply because they were convenient during bring-up.','Ship a deliberate runtime closure.','oe-pkgdata-util list-pkg-files training-hello','Confirm the runtime executable belongs to the package selected by the image.' ],
 ['Build','Distinguish rootfs and disk artifacts','Rootfs assembly resolves runtime packages into a directory. Image tasks turn it into filesystem artifacts; WIC can compose a partitioned disk image when configured. A rootfs archive is not automatically a bootable disk for every board. Query the configured image types and consult the machine-specific boot layout before selecting an artifact.','Artifact format must match the deployment procedure.','bitbake-getvar -r training-image IMAGE_FSTYPES\nbitbake training-image','Locate artifacts in tmp/deploy/images/<machine>/.' ],
 ['Inspect','Compare the delivered inventory','Find the manifest associated with the generated image and verify the requested package and version. Compare against a prior manifest so unexpected additions are visible. Do not inspect an old symlink target from a different build. Retain checksums of the actual deployed artifacts alongside the manifest to connect build evidence to the tested target.','A manifest is useful only when tied to the deployed artifact.','find tmp/deploy/images -name "training-image*.manifest"','Inspect the matching manifest and record the resolved artifact identity.' ],
 ['Run','Close the loop on the target','Boot the matching machine image and run training-hello. Record kernel identity, application output and the artifact checksum used for deployment. A successful package listing on the workstation is not a runtime test. For physical media, verify destination devices before writing; this lesson intentionally does not supply a blind disk-write command.','Delivery evidence spans metadata, artifact and running device.','uname -a\ntraining-hello','The expected program runs on the intended target.' ]],lab:{objective:'Create a maintained image recipe containing the training application.',setup:'A working training-hello recipe and a bootable machine configuration. Use QEMU first when possible.',commands:'bitbake-getvar -r training-image IMAGE_INSTALL\nbitbake training-image\nfind tmp/deploy/images -name "training-image*.manifest"',expected:'The application package appears in the matching manifest and runs on the deployed image.',troubleshooting:'Check package names, append spacing, selected image and deploy timestamps. Building an application recipe alone does not update the image.',deliverable:'Image recipe, manifest comparison, artifact checksum and target output.'},quiz:{question:'Does building a recipe automatically add it to every image?',options:['Yes','No','Only for local sources'],answer:1,why:'Image composition must explicitly request the runtime package or a package group that includes it.'}}),
lesson({id:'service-recipe-lab',chapter:'applications',title:'Package a supervised foreground service',description:'Connect a unit, executable, runtime package and image policy without losing readiness and identity boundaries.',scene:'services',source:'Mastering-Embedded-Linux-Development-4th-Edition.pdf',sourceChapter:'Starting Up',goals:['Install through the systemd class','Keep the application in the foreground','Verify identity, logs and restarts'],steps:[
 ['Process','Let the supervisor own lifetime','A simple service should remain in the foreground rather than forking into the background from a shell wrapper. systemd tracks the main process and can collect standard output in the journal. Choose Type=simple for a foreground program that does not implement a readiness protocol; do not claim that process creation proves application readiness.','Process lifetime and functional readiness are separate observations.','[Service]\nType=simple\nExecStart=/usr/bin/training-watch\nRestart=on-failure','The service manager tracks the foreground process.' ],
 ['Identity','Use a restricted runtime account','Run the service under a dedicated account where its hardware and data access permit. Integrate account creation with the useradd class rather than assuming an account already exists. Hardening options such as NoNewPrivileges and ProtectSystem can reduce accidental access, but test them against the real application: a policy that prevents required device access is not a working integration.','Least privilege must preserve the required function.','User=trainingwatch\nNoNewPrivileges=true\nProtectSystem=strict\nProtectHome=true','Provision trainingwatch in maintained metadata before enabling the unit.' ],
 ['Recipe','Use standard unit integration','Inherit systemd and install the unit under the effective systemd_system_unitdir. That variable already denotes the system unit directory in the standard integration; adding another system path segment can install the file somewhere the manager does not search. Declare the service name for the correct output package and verify package file ownership.','Query directory variables instead of guessing filesystem layout.','inherit systemd\nSYSTEMD_SERVICE:${PN} = "training-watch.service"\nSYSTEMD_AUTO_ENABLE:${PN} = "enable"','The recipe installs both executable and unit into its staging root.' ],
 ['Policy','Require the intended init environment','Selecting systemd is distro policy, not something one application recipe should silently impose. Verify the image actually boots systemd as PID 1 and includes the service package. Unit ordering such as After= does not start dependencies by itself and does not prove a network endpoint is ready. Implement bounded retry or an explicit application readiness contract as needed.','Ordering, dependency and readiness are different mechanisms.','ps -p 1 -o comm=\nsystemctl status training-watch\nsystemctl show training-watch -p User -p MainPID','PID 1 and the service runtime identity match the intended design.' ],
 ['Test','Observe failures without creating a loop','Use a development image to inspect journal messages, controlled failure and stop behavior. Configure start limits and application retry policy so a persistent defect does not create an unbounded restart storm. Never test a hardware watchdog by stopping feeds on an unattended production device. Save logs before changing configuration so a restart cannot erase the original evidence.','A service being active is not a complete health check.','journalctl -u training-watch -b\nsystemctl stop training-watch\nsystemctl start training-watch','Verify functional output, stop behavior and bounded recovery separately.' ]],lab:{objective:'Ship and validate a foreground service through an owned recipe.',setup:'A systemd-based development image, a foreground training-watch executable and a recipe that provisions trainingwatch using useradd. Unit installation uses ${D}${systemd_system_unitdir}.',commands:'bitbake training-watch\noe-pkgdata-util list-pkg-files training-watch\n# On target:\nsystemctl status training-watch\njournalctl -u training-watch -b\nsystemctl show training-watch -p User -p MainPID',expected:'The unit is packaged, enabled as intended, runs under the dedicated identity and emits observable functional output.',troubleshooting:'Check PID 1, unit path, executable permission, interpreter package, account provisioning and journal errors before relaxing hardening.',deliverable:'Recipe, unit, runtime identity evidence and functional/restart test record.'},quiz:{question:'Does After=network.target prove a remote server is reachable?',options:['Yes','No','Only with Type=simple'],answer:1,why:'Ordering is not remote application readiness; design explicit checks and bounded retry.'}}),
lesson({id:'readonly-overlay',chapter:'storage',title:'Design a read-only root filesystem',description:'Separate immutable software, volatile state and persistent product data.',scene:'filesystem',sourceChapter:'Creating a Root Filesystem',goals:['Inventory runtime writes','Choose persistence boundaries','Test reboot and rollback behavior'],steps:[
 ['Inventory','Find every intended write','A read-only root filesystem is an architectural decision, not merely a mount option. Applications, logs, credentials and update state all need explicit locations. List which data must survive reboot and which may disappear. Trace a development boot for write failures before making a production policy, and distinguish application data from generated machine identity.','Software immutability does not eliminate state.','findmnt /\nfindmnt /var\nfindmnt /run','Record current mount options and the owner of each writable path.' ],
 ['Enable','Use the image feature as a build check','Enable read-only-rootfs in the owned training image and build it. The build must complete required package installation work without relying on first-boot writes into the immutable root. Do not hide failures by making the entire filesystem writable. Resolve the failing post-install behavior or select components compatible with the policy.','Build-time completion and runtime write behavior both need validation.','IMAGE_FEATURES:append = " read-only-rootfs"','Review rootfs task diagnostics for deferred installation work.' ],
 ['Volatile','Keep temporary state temporary','Use tmpfs-backed runtime directories for sockets, PID files and transient caches where loss on reboot is acceptable. Size memory consumption deliberately: tmpfs allocations compete with application memory. A volatile journal can be useful during development, but product support may require an explicitly bounded persistent logging strategy on a separate writable area.','A volatile location is a lifetime policy, not free storage.','findmnt -t tmpfs\ndf -h /run','Check capacity and confirm transient state is recreated at startup.' ],
 ['Persistent','Constrain writable product data','Put retained configuration and records on an explicit data partition with ownership, quotas or capacity management, and migration rules. Overlayfs can provide a writable upper layer, but it introduces its own lifecycle and rollback questions. Do not use an overlay to avoid deciding which writes should persist. Test upper-layer compatibility across image updates.','Persistent state must remain compatible with rollback.','findmnt -o TARGET,SOURCE,FSTYPE,OPTIONS','Document data mount, write permissions and versioned schema policy.' ],
 ['Validate','Test cold boot and interrupted updates','Reboot the development target and verify that transient state disappears while required product records survive. Test application startup with a full or unavailable data partition. In an A/B design, roll back the software and confirm it can read retained data. A read-only rootfs reduces accidental root changes but does not by itself provide verified boot or data integrity.','Read-only, authenticated and recoverable are different guarantees.','systemctl --failed\njournalctl -b -p err','Evidence covers boot, persistence, capacity failure and rollback compatibility.' ]],lab:{objective:'Build a read-only training image with documented state ownership.',setup:'A disposable target or QEMU image with serial access and a recovery path. Do not remount a production rootfs during the exercise.',commands:'bitbake training-image\n# On target:\nfindmnt -o TARGET,SOURCE,FSTYPE,OPTIONS\nsystemctl --failed\njournalctl -b -p err',expected:'The root is read-only, required services work, and every intended write has a declared lifetime and destination.',troubleshooting:'Inspect rootfs post-install failures, runtime write errors, directory ownership and tmpfs capacity. Avoid granting global write access as a workaround.',deliverable:'Write-path inventory, mount design and reboot/failure test matrix.'},quiz:{question:'Does a read-only rootfs authenticate its contents?',options:['Yes','No','Only on ext4'],answer:1,why:'Authentication and integrity enforcement require separate trust mechanisms.'}}),
lesson({id:'power-management',chapter:'kernel',title:'Measure power and validate suspend',description:'Connect workload, frequency, device runtime PM and system sleep to measured product behavior.',scene:'power',sourceChapter:'Managing Power',goals:['Separate idle and suspend','Measure against a workload','Test wake sources and recovery'],steps:[
 ['Baseline','Start with a repeatable workload','Power optimization needs a measured baseline: board revision, supply voltage, peripherals, workload, ambient conditions and software version. CPU utilization alone is not a power measurement. Capture supply current with suitable external equipment and record latency and throughput so a lower reading cannot conceal a system that stopped doing useful work.','Optimize energy for a defined job, not an isolated number.','uname -a\ncat /sys/devices/system/cpu/online','Record external power measurements alongside the workload definition.' ],
 ['Frequency','Observe policy before changing it','CPU frequency policy can trade performance and energy, but available drivers, governors and operating points depend on the BSP. Read the exposed policy files first. Do not hard-code a frequency copied from another SoC or disable thermal protection to sustain a benchmark. Compare completed work and response latency as well as average current.','Frequency settings are platform capabilities, not portable constants.','grep . /sys/devices/system/cpu/cpufreq/policy*/scaling_governor\ngrep . /sys/devices/system/cpu/cpufreq/policy*/scaling_available_frequencies','Some platforms do not expose every optional file.' ],
 ['Devices','Understand runtime power management','Runtime PM allows individual devices to enter lower-power states while the system remains running. Driver support, dependency ordering and wake requirements determine whether this works. Inspect one known device and its documentation before changing power/control. A sleeping peripheral that cannot resume reliably can break a product even if the idle current looks excellent.','System sleep and device runtime PM have different scopes.','find /sys/devices -path "*/power/runtime_status" -type f 2>/dev/null | head','Choose one documented device and observe transitions under a controlled workload.' ],
 ['Suspend','Plan the wake path first','System suspend can interrupt remote access. Use serial console access, a verified wake source and a recovery plan on a development board. Read supported states and wake configuration; do not run a suspend write from this website blindly. Board peripherals, wake wiring and driver support determine the procedure. Validate the selected vendor guide against the actual carrier revision.','Do not enter a state without a tested route back.','cat /sys/power/state\ncat /sys/power/mem_sleep','Read-only discovery; supported states vary by platform.' ],
 ['Regression','Test repeated functional recovery','One successful wake is insufficient. Repeat sleep/wake cycles and verify network reconnection, sensor operation, timekeeping, storage and application deadlines afterward. Measure wake latency and suspended current externally. Keep kernel logs and count failures. A device that wakes but silently loses a peripheral has not passed the system-level test.','Recovery means the product resumes its job, not merely its prompt.','dmesg | tail -n 100\ncat /proc/interrupts','Retain cycle counts, wake causes, latency and functional checks.' ]],lab:{objective:'Produce a safe power-management experiment plan and measured results.',setup:'Development board, external current measurement, serial console and a documented wake source. Discovery commands are read-only; use the exact vendor suspend procedure only after reviewing recovery.',commands:'cat /sys/power/state\ncat /sys/power/mem_sleep\ncat /sys/devices/system/cpu/online\ndmesg | tail -n 100',expected:'A baseline and repeatable test record distinguish active, idle and suspended behavior with functional recovery evidence.',troubleshooting:'Check wake-source wiring, driver support, console behavior and peripheral resume logs. Never bypass thermal safeguards to force a result.',deliverable:'Power/latency table, wake design, repeated-cycle results and retained logs.'},quiz:{question:'What is a valid suspend acceptance test?',options:['The display went dark','The prompt returned once','Measured low-power entry plus repeated functional recovery'],answer:2,why:'The product must save power and reliably resume its required workload.'}}),
lesson({id:'python-applications',chapter:'applications',title:'Package Python without target-side drift',description:'Integrate Python modules and services through reproducible metadata rather than ad-hoc pip installs.',scene:'packages',source:'Mastering-Embedded-Linux-Programming-3rd-Edition.pdf',sourceChapter:'Python',goals:['Separate build backend and runtime dependencies','Build offline from declared inputs','Constrain service resources'],steps:[
 ['Boundary','Decide what Python owns','Python is useful for orchestration, network interfaces and tools, but interpreter startup, memory use and native extensions affect embedded budgets. Define the application boundary and measure it on target. Keep hard timing requirements out of an unmeasured general-purpose interpreter path. A working workstation virtual environment is a development aid, not the product package definition.','Choose the language against measured product constraints.','python3 --version\n/usr/bin/time -v python3 -c "print(\"training\")"','Measure on the target with the tools available in the development image.' ],
 ['Build','Choose the class for the real backend','Inspect pyproject.toml and the selected release classes. Setuptools, Poetry and other backends need the matching supported integration rather than a copied generic command. Declare source checksums, license evidence and pinned inputs. Avoid allowing a build task to download undeclared dependencies from a package index: it defeats offline and provenance expectations.','The build backend is an input to recipe design.','bitbake-layers show-recipes "python3-*"\n# Inspect upstream pyproject.toml and the release class documentation.','Select a backend class based on the package, not its language alone.' ],
 ['Runtime','Declare imports and native library requirements','Python code may need separately split standard-library packages or third-party modules that are not in a minimal image. Native extensions also need target ABI-compatible libraries. Inspect imports and test on a minimal image so a large developer image does not hide missing packages. Distinguish the tools needed to build a wheel from packages needed to execute it.','A successful wheel build is not proof of a complete runtime closure.','RDEPENDS:${PN} += "python3-core"\n# Add actual imported-module output packages after checking package data.','The recipe declares the application-specific runtime closure.' ],
 ['Service','Own paths and execution environment','Run the application with an explicit interpreter path, working directory and service identity. Install code into maintained package paths and put writable records in the declared data area. Avoid writable code directories or target-side pip upgrades that silently replace released files. Capture stdout/stderr through the supervisor and design bounded retries for unavailable endpoints.','Released code and writable application data should have separate ownership.','ExecStart=/usr/bin/python3 -m training_app\nRestart=on-failure','A unit invokes the packaged module under a restricted account.' ],
 ['Validate','Test imports, startup and resource limits','Run import tests and the primary application workflow on the generated image. Measure startup time and peak memory, then test network loss and malformed inputs. Keep development tools out of the production image unless required by support policy. Archive the package/version inventory so future vulnerability and compatibility investigations can identify the exact interpreter and modules.','Reproducibility includes the interpreter and imported dependencies.','python3 -c "import training_app; print(training_app.__file__)"\npython3 -m training_app --help','The module loads from the intended packaged location.' ]],lab:{objective:'Integrate a small Python module through a recipe and supervised runtime.',setup:'An owned module with declared backend, license and dependencies, plus a development image containing measurement tools.',commands:'bitbake training-python\noe-pkgdata-util list-pkg-files training-python\n# On target:\npython3 -c "import training_app; print(training_app.__file__)"',expected:'The application imports and runs without target-side pip installation or network dependency fetching.',troubleshooting:'Check split Python packages, extension ABI, backend class, interpreter path and writable-data permissions.',deliverable:'Recipe, import inventory, service definition and startup/memory evidence.'},quiz:{question:'Why avoid ad-hoc pip upgrades on released targets?',options:['Python cannot run on ARM','They can bypass the maintained image inventory and reproducibility contract','They always require a reboot'],answer:1,why:'Released software must remain tied to controlled inputs and an auditable package inventory.'}}),
lesson({id:'qt-graphics',chapter:'applications',title:'Trace a Qt application through the display stack',description:'Connect application, compositor, graphics driver and physical display before tuning UI behavior.',scene:'graphics',source:'Mastering-Embedded-Linux-Development-4th-Edition.pdf',sourceChapter:'Qt',goals:['Separate application and display stack failures','Use a matching Qt SDK','Measure startup and rendering'],steps:[
 ['Stack','Map the path to visible pixels','A graphical product combines the application, a Qt platform integration, possibly a Wayland compositor, graphics drivers and display hardware. A blank panel is not automatically an application bug. Record the selected BSP, display connection and session backend. Follow one known-good vendor demo through the same path before introducing your own application.','Debug the first missing boundary rather than changing every layer.','echo "$XDG_SESSION_TYPE"\necho "$WAYLAND_DISPLAY"\nls /dev/dri','Environment and device nodes are observations, not proof that rendering works.' ],
 ['Toolchain','Match the SDK to the image','Qt headers, libraries, plugins and generated tools must match the image integration. Generate or install the SDK intended for that release and image. Use its environment in a clean shell and configure the application with the supported build system. Do not mix host desktop Qt libraries with target libraries because the configure step happened to succeed.','A matching SDK avoids invisible host-target library mixing.','bitbake <qt-enabled-image> -c populate_sdk\n# Install the generated SDK and source its environment script.','Use the vendor image/toolchain guide for exact supported image names.' ],
 ['Package','Deliver plugins and resources deliberately','The application binary is only part of the runtime. Qt platform plugins, QML imports, fonts and resource files may be split into separate packages. Declare the actual runtime closure and inspect the manifest. Avoid installing every Qt module simply to hide an unknown dependency; identify which component the application really requires.','Plugin discovery failures are packaging and environment evidence.','oe-pkgdata-util list-pkg-files <application-package>','Inspect application resources and required plugin packages in the image.' ],
 ['Diagnose','Inspect the session before forcing a backend','Run the application in the intended graphical session and retain plugin diagnostics. A process started over SSH may lack the same environment and socket permissions as the display session. Do not use a broad root login to hide permission problems. Treat backend forcing as a controlled diagnostic step, not a permanent fix without understanding the session contract.','The same binary can behave differently under another session identity.','QT_DEBUG_PLUGINS=1 /usr/bin/training-ui','Inspect plugin loading, library errors and session access on a development target.' ],
 ['Acceptance','Measure the visible product behavior','Measure cold startup, first meaningful frame, input responsiveness, memory and display recovery. Test unplug/reconnect only where the hardware supports it. A running process with a black window has not passed. Keep screenshots or photographs with artifact identity and display configuration so the evidence captures the actual visible result, not just an exit code.','Graphical acceptance requires observing pixels and input.','journalctl -b | tail -n 100','Record visible output, interaction and measured timing under the intended workload.' ]],lab:{objective:'Build and validate a minimal Qt application on a supported graphics image.',setup:'Matching board/display, Qt-enabled BSP image and SDK. Use the linked vendor Qt guide for release-specific build details.',commands:'bitbake <qt-enabled-image> -c populate_sdk\n# Build and package your application with the matching SDK.\n# On target, in the intended session:\nQT_DEBUG_PLUGINS=1 /usr/bin/training-ui',expected:'A visible, responsive application using packaged plugins and the intended graphics backend.',troubleshooting:'Check compositor/session state, plugin packages, library ABI, display connection and access permissions separately.',deliverable:'Application recipe, runtime package inventory, visible-output evidence and startup measurements.'},quiz:{question:'What does a successful application launch prove about its display?',options:['All pixels are correct','Nothing by itself about visible rendering','The panel uses HDMI'],answer:1,why:'The compositor, plugin, driver and physical output still need observation.'}}),
lesson({id:'container-applications',chapter:'systems',title:'Design containers as part of the product',description:'Keep a containerized application distinct from the kernel, device access and host update contract.',scene:'containers',source:'Mastering-Embedded-Linux-Development-4th-Edition.pdf',sourceChapter:'Containers',goals:['Explain the shared kernel boundary','Pin application and host inputs','Constrain privileges and writable state'],steps:[
 ['Boundary','A container shares the host kernel','Containers package userspace processes and isolation policy; they do not bring an independent Linux kernel like a virtual machine. Kernel features, drivers and security updates remain host responsibilities. Decide whether the deployment model actually needs independent application delivery before adding runtime footprint, storage and operational complexity to an embedded system.','Container isolation depends on the host kernel and policy.','uname -r\n# Compare host and container kernel identity in a development environment.','The kernel boundary remains the host system.' ],
 ['Host','Integrate the runtime deliberately','Choose runtime and compatible layer revisions for the selected Yocto release. Verify required kernel features and filesystem behavior against the runtime documentation. A vendor demo with Docker enabled is a starting point for learning, not proof the product has acceptable storage use or attack surface. Measure image and writable-layer growth.','The container runtime is part of the maintained host platform.','bitbake-layers show-layers\n# Inspect the selected runtime recipe and kernel requirements.','Record compatible layer commits and the runtime version.' ],
 ['Inputs','Pin images and track their inventory','A mutable image tag is not an immutable release input. Record a digest and the component inventory of both the host and application image. Rebuilding the host does not automatically rebuild or scan the container application. Define who owns application signing, registry access, offline installation and rollback compatibility with the host API.','Two delivery streams require two explicit provenance records.','docker image inspect <image> --format "{{json .RepoDigests}}"','Use the selected runtime equivalent if Docker is not installed.' ],
 ['Privileges','Expose only required interfaces','Avoid privileged mode as a general solution to device access. Grant the specific device nodes, capabilities, mounts and network access the application needs, and test without broad grants. Use read-only application layers where possible and bound writable data and logs. Do not assume a container root identity is harmless on the host.','Narrow device access is a product contract.','docker inspect <container>','Review privileged flag, capabilities, mounts, user and restart policy.' ],
 ['Failure','Test host and application recovery together','Test application crash, registry loss, full writable storage, power interruption and host update rollback. A container restart policy cannot repair a broken kernel or incompatible device interface. Define readiness checks and retain the prior application image until the new one passes. Confirm the rollback application can still use persistent data and the restored host.','Independent delivery does not mean independent compatibility.','docker logs <container>\ndocker stats --no-stream','Retain recovery results and resource usage, not only successful startup.' ]],lab:{objective:'Evaluate a containerized application against an embedded product threat and recovery model.',setup:'A disposable development target with a supported runtime. Do not expose the Docker socket or grant privileged access to untrusted applications.',commands:'docker image inspect <image>\ndocker inspect <container>\ndocker stats --no-stream\ndocker logs <container>',expected:'Pinned image identity, explicit host requirements, restricted access and tested recovery.',troubleshooting:'Separate host kernel/runtime failures from application failures. Check storage capacity and permissions before broadening privileges.',deliverable:'Host/application compatibility matrix, digest inventory and failure/recovery test record.'},quiz:{question:'Who supplies a Linux container kernel?',options:['The host','Every image carries its own running kernel','The registry'],answer:0,why:'Containers share the host kernel, so host updates and kernel interfaces remain product responsibilities.'}}),
lesson({id:'rust-applications',chapter:'applications',title:'Integrate Rust with a target-aware build',description:'Connect Cargo inputs, target ABI, native dependencies and reproducible Yocto packaging.',scene:'compile',source:'Mastering-Embedded-Linux-Development-4th-Edition.pdf',sourceChapter:'Rust',goals:['Pin Cargo dependencies','Separate host build scripts from target code','Check ELF and runtime behavior'],steps:[
 ['Scope','Know what Rust changes and what it does not','Rust can reduce certain memory-safety defects in safe code, but it does not eliminate logic errors, unsafe boundaries, resource exhaustion or timing problems. Start with a small command-line application and a clear failure contract. Kernel drivers and ordinary Linux userspace binaries are different integration targets; this exercise is userspace.','Language guarantees do not replace system-level validation.','cargo new --bin training-rust\ncd training-rust\ncargo test','A host-side test fixture is useful before target packaging.' ],
 ['Inputs','Retain the dependency lock and source identity','Use a committed Cargo.lock for the application and account for all fetched crates in the recipe workflow. The build should not contact undeclared registries during compilation. Crate licenses and checksums are part of the inventory, not an exception because Cargo resolved them. Use the release-supported Cargo recipe tooling and review its generated output.','A lockfile records resolution but does not by itself make a build offline.','cargo test --locked\ngit diff -- Cargo.toml Cargo.lock','Review changes to both manifest and resolved dependency graph.' ],
 ['Targets','Distinguish host execution from target compilation','Cargo build scripts and procedural macros execute on the build host, while the final application targets the device. Native libraries introduce additional compiler, linker and pkg-config requirements. Use the selected release cargo integration rather than manually substituting a target triple into a workstation command and hoping all subprocesses inherit the right environment.','One build can contain both host tools and target artifacts.','inherit cargo\n# Configure pinned source and declared crate inputs for the selected release.','Inspect task logs to distinguish host build tools from target compiler/linker calls.' ],
 ['Package','Inspect the delivered ELF and libraries','A target binary still needs the correct ABI and any dynamically linked runtime libraries. Inspect architecture and interpreter using target-aware tooling or readelf, then examine generated package dependencies. A statically linked deployment has its own size and update tradeoffs; do not assume it is universally smaller or easier to maintain.','An ELF file must match the target loader and library contract.','readelf -h <target-binary>\nreadelf -l <target-binary>\nreadelf -d <target-binary>','Check machine architecture, interpreter and required shared libraries.' ],
 ['Runtime','Exercise errors and resource boundaries','Run the packaged application on a minimal matching image. Test invalid inputs, missing files, unavailable endpoints and shutdown behavior. A panic message is diagnostic evidence, not a recovery design. Measure memory and startup under realistic workload and retain debug symbols for postmortem analysis. Unsafe FFI code deserves explicit boundary tests.','The target acceptance test includes failure and shutdown paths.','training-rust --help\n# Run the application-specific valid and invalid input tests.','Record exit status, diagnostics, resource use and target artifact identity.' ]],lab:{objective:'Package a pinned Rust userspace application and validate target ABI and failure behavior.',setup:'Release-compatible Rust/Cargo metadata and an owned application with Cargo.lock. Recipe generation must account for all source/crate inputs.',commands:'cargo test --locked\nbitbake training-rust\noe-pkgdata-util list-pkg-files training-rust\n# Inspect the built target ELF and run it on the matching image.',expected:'Declared source inputs, target-correct ELF and repeatable success/failure behavior without undeclared build-time downloads.',troubleshooting:'Check build-script host tools, target linker/sysroot, native dependencies and crate source declarations separately.',deliverable:'Recipe, lockfile, crate/license inventory, ELF inspection and target test results.'},quiz:{question:'Where do Cargo build scripts normally execute during cross compilation?',options:['On the build host','Only on the target board','Inside the bootloader'],answer:0,why:'Build-time helpers execute on the host even though the final application is compiled for the target.'}})
];
